(function(){
  const cx = W()/2, cy = H()/2;
  const safeR = Math.min(W(),H())*0.27;
  const colors = PALETTE;
  const N = 120;
  const sparks = [];
  for(let i=0;i<N;i++){
    sparks.push({
      a: Math.random()*Math.PI*2,
      speed: 0.05+Math.random()*0.08,
      rBase: safeR*1.4 + Math.random()*safeR*1.3,
      rAmp: safeR*0.25*Math.random(),
      rFreq: 0.5+Math.random()*1.5,
      phase: Math.random()*Math.PI*2,
      size: 0.6+Math.random()*1.8,
      colorIdx: Math.floor(Math.random()*colors.length),
      trail: []
    });
  }

  function starPts(){ return [[0,-18],[5,-5],[18,-3],[8,5],[11,18],[0,9],[-11,18],[-8,5],[-18,-3],[-5,-5]]; }
  function heartPts(){ return [[0,10],[-10,-4],[-6,-14],[0,-8],[6,-14],[10,-4]]; }
  function butterflyPts(){ return [[0,0],[-14,-10],[-18,4],[-8,10],[0,4],[8,10],[18,4],[14,-10]]; }

  const clusters = [
    {angle: Math.PI*0.15, radius: safeR*2.0, pts: starPts(), rot: 0, rotSpeed: 0.0006},
    {angle: Math.PI*1.05, radius: safeR*2.1, pts: heartPts(), rot: 0, rotSpeed: -0.0004},
    {angle: Math.PI*1.75, radius: safeR*1.9, pts: butterflyPts(), rot: 0, rotSpeed: 0.0005}
  ];

  let t0 = performance.now();

  function drawHand(time){
    const hx = W()*0.10, hy = H()*0.90;
    ctx.save();
    ctx.translate(hx,hy);
    const pulse = 0.5+0.5*Math.sin(time*0.0007);
    ctx.globalAlpha = 0.12+0.06*pulse;
    ctx.fillStyle = colors[1];
    ctx.beginPath();
    ctx.moveTo(0,0);
    ctx.bezierCurveTo(-30,-10,-34,-50,-14,-70);
    ctx.bezierCurveTo(-8,-80,4,-80,6,-68);
    ctx.bezierCurveTo(10,-82,22,-82,22,-68);
    ctx.bezierCurveTo(26,-84,38,-82,36,-66);
    ctx.bezierCurveTo(44,-70,52,-60,44,-46);
    ctx.bezierCurveTo(50,-30,40,-4,20,10);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function frame(time){
    const dt = time - t0;
    t0 = time;

    for(const s of sparks){
      s.a += s.speed*dt*0.001;
      const r = s.rBase + s.rAmp*Math.sin(time*0.001*s.rFreq + s.phase);
      const x = cx + Math.cos(s.a)*r;
      const y = cy + Math.sin(s.a)*r*0.72;
      s.trail.push({x,y});
      if(s.trail.length>10) s.trail.shift();

      for(let i=0;i<s.trail.length;i++){
        const p = s.trail[i];
        const alpha = (i/s.trail.length)*0.5;
        ctx.beginPath();
        ctx.fillStyle = colors[s.colorIdx];
        ctx.globalAlpha = alpha*0.6;
        ctx.arc(p.x,p.y, s.size*(i/s.trail.length), 0, Math.PI*2);
        ctx.fill();
      }
      ctx.globalAlpha = 0.9;
      ctx.beginPath();
      ctx.fillStyle = colors[s.colorIdx];
      ctx.shadowColor = colors[s.colorIdx];
      ctx.shadowBlur = 6;
      ctx.arc(x,y,s.size,0,Math.PI*2);
      ctx.fill();
      ctx.shadowBlur = 0;
    }
    ctx.globalAlpha = 1;

    drawHand(time);

    for(const c of clusters){
      c.rot += c.rotSpeed*dt;
      const bx = cx + Math.cos(c.angle)*c.radius;
      const by = cy + Math.sin(c.angle)*c.radius*0.8;
      ctx.save();
      ctx.translate(bx,by);
      ctx.rotate(c.rot);
      ctx.strokeStyle = colors[2];
      ctx.lineWidth = 1;
      ctx.globalAlpha = 0.35;
      ctx.beginPath();
      c.pts.forEach((p,i)=>{
        if(i===0) ctx.moveTo(p[0],p[1]); else ctx.lineTo(p[0],p[1]);
      });
      ctx.closePath();
      ctx.stroke();
      c.pts.forEach((p,i)=>{
        const tw = 0.5+0.5*Math.sin(time*0.002+i+c.angle);
        ctx.beginPath();
        ctx.globalAlpha = 0.4+0.5*tw;
        ctx.fillStyle = colors[0];
        ctx.shadowColor = colors[0];
        ctx.shadowBlur = 8;
        ctx.arc(p[0],p[1],1.6+tw,0,Math.PI*2);
        ctx.fill();
      });
      ctx.shadowBlur=0;
      ctx.restore();
    }
    ctx.globalAlpha = 1;

    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
